// ============================================================

import { state, persist } from '../00_State.js';
import { ShowToast } from '../04_Modals/01_Modal_Core.js';

export function IsStandalone() {
  return typeof document !== 'undefined' && !!document.getElementById('rd-inline-bundle');
}

export function buildSaveHtml(stateData) {
  if (IsStandalone()) {
    const cssEl = document.getElementById('rd-inline-css');
    const bundleEl = document.getElementById('rd-inline-bundle');
    const iconEl = document.querySelector('link[rel="icon"]');
    const dataJson = JSON.stringify({ rd: stateData })
      .replace(/</g, '\u003c')
      .replace(/\u2028/g, '\u2028')
      .replace(/\u2029/g, '\u2029');
    const logoJson = JSON.stringify((typeof window.__RD_LOGO__ === 'string') ? window.__RD_LOGO__ : '');
    const favicon = iconEl ? iconEl.getAttribute('href') : 'data:,';
    return '<!DOCTYPE html>\n' +
      '<html lang="en" data-theme="dark">\n' +
      '<head>\n' +
      '<meta charset="UTF-8" />\n' +
      '<meta name="viewport" content="width=device-width, initial-scale=1.0" />\n' +
      '<title>R&amp;D — Research &amp; Development Library</title>\n' +
      '<link rel="icon" type="image/svg+xml" href="' + favicon + '" />\n' +
      '<style id="rd-inline-css">\n' + (cssEl ? cssEl.textContent : '') + '\n</style>\n' +
      '</head>\n' +
      '<body>\n' +
      '<div id="rd-root"><div class="rd-splash"><div class="rd-splash-spinner"></div><div class="rd-splash-title">R&amp;D</div><div class="rd-splash-sub">RESEARCH &amp; DEVELOPMENT LIBRARY</div></div></div>\n' +
      '<script>\n' +
      'window.__RD_INITIAL_DATA__ = ' + dataJson + ';\n' +
      'window.__RD_LOGO__ = ' + logoJson + ';\n' +
      '<\/script>\n' +
      '<script id="rd-inline-bundle">\n' + (bundleEl ? bundleEl.textContent : '') + '\n<\/script>\n' +
      '</body>\n' +
      '</html>';
  }
  const dataJson = JSON.stringify({ rd: stateData })
    .replace(/</g, '\u003c')
    .replace(/\u2028/g, '\u2028')
    .replace(/\u2029/g, '\u2029');
  return RD_TEMPLATE.replace('__RD_DATA_JSON__', function() { return dataJson; });
}

export function DownloadStandaloneHTML() {
  const rd = state.rd;
  rd.meta.exportedAt = new Date().toISOString();
  rd.meta.exportCount = (rd.meta.exportCount || 0) + 1;
  persist(true);

  ShowToast('info', 'Building standalone HTML', 'Bundling app + CSS + modules + your data…');
  try {
    const html = buildSaveHtml(rd);
    const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const d = new Date();
    const pad = (n) => String(n).padStart(2, '0');
    a.href = url;
    a.download = 'RD-Library-' + d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()) + '-' + pad(d.getHours()) + pad(d.getMinutes()) + '.html';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 4000);
    ShowToast('success', 'Standalone HTML saved', 'One file: app + library. Open it anywhere, keep editing, export again.');
  } catch (err) {
    console.error('[R&D] standalone export failed:', err);
    ShowToast('error', 'Export failed', err.message || 'Could not bundle application sources.');
  }
}

export const RDSaveButton = {
  IsStandalone,
  buildSaveHtml,
  DownloadStandaloneHTML,
  get RD_TEMPLATE() { return RD_TEMPLATE; }
};
if (typeof window !== 'undefined') {
  window.RDSaveButton = RDSaveButton;
}

